decisions:
if (try engine_refusal.of(srv.engine, cx, &request)) |message| return cx.refuse(message);
// port note (af9777b49): the fork's JSON channel — a structure request answers JSON beside offered tools
const response_channel: ResponseChannel = if (request.structure) |st| switch (st.kind) {
    .json, .json_schema => .structured_json,
    else => .automatic,
} else .automatic;
return .{ .response_channel = response_channel, .input = input, .request = request, .prompt_len = rendered.ids.len, .received = received, .thinking = thinking, .reasoning = reasoning, .effort = effort, .sampled = sampling != null, .drafts = drafts, .token_ids = flag(f, "return_token_ids") orelse false, .stops = stops_opt, .preparing = preparing, .frames = rendered.frames };

const gen_thinking = prepared.reasoning or (srv.text.vtable.format != .kimi and srv.info.capability(.reasoning) and reply_text.isChannel(srv.markers));
var gen: Generation = .{ .srv = srv, .a = a, .box = &box, .id = id, .asked = input.cancel, .reply_id = input.id, .seed = if (request.sampling) |v| v.seed else null, .sink = sink, .thinking = gen_thinking, .chat = input.prompt == null,
    // port note (af9777b49): the fork's TF_THINK_OFF_SPLIT hold, and the JSON channel takes no tools
    .think_off_split = if (!gen_thinking and input.prompt == null and prepared.response_channel != .structured_json and request.logprobs == null) think_off_split.hold() else 0,
    .stops = .{ .strings = stops_opt.strings }, .ignore_eos = stops_opt.ignore_eos, .max_tokens = request.max_tokens, .response_channel = prepared.response_channel, .tools = if (prepared.response_channel == .structured_json) &.{} else input.tools, .token_ids = prepared.token_ids, .lp = if (request.logprobs != null) .{ .positions = if (sink) |s| s.tokens != null else false } else null, .loop_stop = request.loop_stop, .single = flag(input.fields, "tool_call_single") orelse false, .recover = input.prompt == null and request.structure == null };
defer srv.noteRequest(prepared.prompt_len, cached_tokens.within(box.cached, prepared.prompt_len), gen.collected.items.len, box.stats.drafted, box.stats.accepted, box.stats.rounds, received, gen.first_ns, gen.last_ns, box.stats.prefill_seconds, if (box.stats.prefill_seconds != null) box.stats.queued_seconds else null);
errdefer if (!gen.engine_done) gen.cancel(); // the engine writes to the mailbox until it says finished
const result: Failure!Reply = blk: {
    if (sink) |s| if (s.begin) |begin| begin(s.ctx, prepared.prompt_len) catch break :blk error.Cancelled;
    if (sink != null and gen.tools.len > 0 and srv.text.vtable.format != .kimi) gen.calls = tool_stream.Streamer.init(a, gen.tools) catch |e| break :blk e;
